mapper.select:
SELECT  FROM tianquan_oauth.oauth_audit_dead_letter
WHERE tenant_id = #{tenantId} AND retain_until <= #{now}
  AND id > #{afterId} AND deleted_at IS NULL ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_audit_dead_letter
SET version = #{po.version}, update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND inbox_pk = #{po.inboxPk}
  AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_audit_dead_letter t
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_time = #{now}, update_user_id = #{actor}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND deleted_at IS NULL AND retain_until <= #{now}
